{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useLongPress",
    "displayName": "useLongPress",
    "keywords": [
      "long press",
      "touch",
      "press and hold",
      "context menu",
      "mobile",
      "ios",
      "safari",
      "gesture",
      "tap"
    ],
    "params": [
      {
        "name": "options",
        "type": "UseLongPressOptions",
        "description": "Configuration object.",
        "required": true
      },
      {
        "name": "options.onLongPress",
        "type": "(point: {x: number; y: number}) => void",
        "description": "Fired with the touch start point once the press is held for delayMs.",
        "required": true
      },
      {
        "name": "options.disabled",
        "type": "boolean",
        "description": "When true, the returned touch handlers are inert.",
        "default": "false"
      },
      {
        "name": "options.delayMs",
        "type": "number",
        "description": "Hold duration before the press fires, in milliseconds.",
        "default": "500"
      },
      {
        "name": "options.moveCancelPx",
        "type": "number",
        "description": "Movement past this distance on either axis cancels the press, treating it as a scroll or drag.",
        "default": "10"
      }
    ],
    "returns": [
      {
        "name": "handlers",
        "type": "UseLongPressHandlers",
        "description": "onTouchStart, onTouchMove, onTouchEnd and onTouchCancel to spread onto the target element."
      }
    ],
    "usage": {
      "description": "Detects a single-finger press-and-hold and reports where it happened, so touch users can reach affordances that a pointer gets from right-click. iOS Safari never synthesizes a contextmenu event on long-press, which makes this the only touch route into a cursor-positioned surface such as ContextMenu. The press cancels on movement, lift, multi-touch or unmount. The hold is timed on the touch events’ own timestamps: when a busy page handles the lift late, a finger held for the full delay still reports its long press, before the lift acts.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use the reported point to position the surface you open, so it appears under the finger."
        },
        {
          "guidance": true,
          "description": "Pair it with the pointer contextmenu handler rather than replacing it; this hook only covers touch."
        },
        {
          "guidance": false,
          "description": "Use it for the primary action of a control; press-and-hold is undiscoverable as the only way to do something."
        }
      ]
    },
    "relatedComponents": [
      "ContextMenu"
    ],
    "relatedHooks": [
      "useClickableContainer",
      "useHotkeys"
    ],
    "importPath": "@astryxdesign/core/hooks",
    "category": "interaction"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
